import React, { useEffect, useRef, useState } from "react";
import { useDispatch } from "react-redux";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import http, { uploadImage } from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { useLocation, useNavigate } from "react-router-dom";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import "../../styles/Layout/_AddNewCategory.scss";

export default function AddNewCategory() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { state } = useLocation();
  const [categoryData, setCategoryData] = useState(state?.data);

  const newCategoryRefOn = useRef(null);
  const newCategoryRefOff = useRef(null);
  const [categoryName, setCategoryName] = useState("");
  const [categoryImageOn, setCategoryImageOn] = useState(null);
  const [categoryImageOff, setCategoryImageOff] = useState(null);

  useEffect(() => {
    if (categoryData) {
      setCategoryName(categoryData?.name);
      setCategoryImageOn(categoryData?.imageOn);
      setCategoryImageOff(categoryData?.imageOff);
    }
  }, [categoryData, state]);

  const uploadData = async () => {
    const formData = {
      name: categoryName,
      imageOn: categoryImageOn,
      imageOff: categoryImageOff,
    };

    if (categoryData?.id) {
      await http
        .put(`${apisPath?.admin?.categories}/${categoryData.id}`, formData)
        .then((res) => {
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    } else {
      await http
        .post(apisPath?.admin?.categories, formData)
        .then((res) => {
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    }
  };

  return (
    <div className="add_new_category">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">
          {categoryData?.id ? "Edit Category" : "Add New Category"}
        </h3>
      </div>
      <div className="add_new_category__content">
        <div className="add_new_category__content__form">
          <div className="add_new_category__content__form__images">
            <div
              className="add_new_category__content__form__images__upload_skelaton"
              onClick={() => newCategoryRefOn?.current?.click()}
            >
              {!categoryImageOn ? (
                <>
                  <FileUploadIcon />
                  <span>Upload category thumbnail on</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 400x400px (Max 5MB, All Image Formats)
                  </small>
                </>
              ) : (
                <img src={categoryImageOn} alt="Category on" />
              )}
            </div>
            <div
              className="add_new_category__content__form__images__upload_skelaton"
              onClick={() => newCategoryRefOff?.current?.click()}
            >
              {!categoryImageOff ? (
                <>
                  <FileUploadIcon />
                  <span>Upload category thumbnail off</span>
                  <small style={{ display: 'block', color: '#666', fontSize: '12px', marginTop: '5px' }}>
                    Recommended: 400x400px (Max 5MB, All Image Formats)
                  </small>
                </>
              ) : (
                <img src={categoryImageOff} alt="Category off" />
              )}
            </div>
          </div>

          <input
            type="file"
            style={{ display: "none" }}
            ref={newCategoryRefOn}
            accept="image/jpeg,image/jpg,image/png,image/gif,image/webp,image/svg+xml,image/bmp,image/tiff,image/x-icon"
            onChange={async (e) => {
                const file = e.target.files[0];
                if (file) {
                  // Check file size (5MB limit)
                  if (file.size > 5 * 1024 * 1024) {
                    dispatch(openTicker({ title: "Error", body: "File size should not exceed 5MB" }));
                    return;
                  }

                  // Check file type - allow comprehensive image formats
                  const allowedTypes = [
                    'image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp',
                    'image/svg+xml', 'image/bmp', 'image/tiff', 'image/x-icon'
                  ];
                  if (!allowedTypes.includes(file.type)) {
                    dispatch(openTicker({ title: "Error", body: "Please select a valid image file (JPEG, PNG, GIF, WebP, SVG, BMP, TIFF, ICO)" }));
                    return;
                  }

                  // Check image dimensions
                  const img = new Image();
                  const objectUrl = URL.createObjectURL(file);

                  img.onload = async function() {
                    URL.revokeObjectURL(objectUrl);

                    // Check if dimensions are within acceptable range (only max dimensions)
                    const maxWidth = 800;
                    const maxHeight = 800;

                    if (img.width > maxWidth || img.height > maxHeight) {
                      dispatch(openTicker({
                        title: "Error",
                        body: `Image dimensions should not exceed ${maxWidth}x${maxHeight}px. Your image is ${img.width}x${img.height}px. Recommended: 400x400px`
                      }));
                      return;
                    }

              await uploadImage(e)
                .then((res) => {
                  setCategoryImageOn(res?.url);
                })
                .catch((err) => {
                  console.log(err);
                });
                  };

                  img.onerror = function() {
                    URL.revokeObjectURL(objectUrl);
                    dispatch(openTicker({ title: "Error", body: "Invalid image file" }));
                  };

                  img.src = objectUrl;
                }
            }}
          />
          <input
            type="file"
            style={{ display: "none" }}
            ref={newCategoryRefOff}
            accept="image/jpeg,image/jpg,image/png,image/gif,image/webp,image/svg+xml,image/bmp,image/tiff,image/x-icon"
            onChange={async (e) => {
                const file = e.target.files[0];
                if (file) {
                  // Check file size (5MB limit)
                  if (file.size > 5 * 1024 * 1024) {
                    dispatch(openTicker({ title: "Error", body: "File size should not exceed 5MB" }));
                    return;
                  }

                  // Check file type - allow comprehensive image formats
                  const allowedTypes = [
                    'image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp',
                    'image/svg+xml', 'image/bmp', 'image/tiff', 'image/x-icon'
                  ];
                  if (!allowedTypes.includes(file.type)) {
                    dispatch(openTicker({ title: "Error", body: "Please select a valid image file (JPEG, PNG, GIF, WebP, SVG, BMP, TIFF, ICO)" }));
                    return;
                  }

                  // Check image dimensions
                  const img = new Image();
                  const objectUrl = URL.createObjectURL(file);

                  img.onload = async function() {
                    URL.revokeObjectURL(objectUrl);

                    // Check if dimensions are within acceptable range (only max dimensions)
                    const maxWidth = 800;
                    const maxHeight = 800;

                    if (img.width > maxWidth || img.height > maxHeight) {
                      dispatch(openTicker({
                        title: "Error",
                        body: `Image dimensions should not exceed ${maxWidth}x${maxHeight}px. Your image is ${img.width}x${img.height}px. Recommended: 400x400px`
                      }));
                      return;
                    }

              await uploadImage(e)
                .then((res) => {
                  setCategoryImageOff(res?.url);
                })
                .catch((err) => {
                  console.log(err);
                });
                  };

                  img.onerror = function() {
                    URL.revokeObjectURL(objectUrl);
                    dispatch(openTicker({ title: "Error", body: "Invalid image file" }));
                  };

                  img.src = objectUrl;
                }
            }}
          />

          <div className="add_new_category__content__form__details">
            <div className="add_new_category__content__form__details__name">
              <label htmlFor="category_name">Category name</label>
              <input
                type="text"
                id="category_name"
                name="category_name"
                value={categoryName}
                placeholder="Enter here"
                maxLength={50}
                onChange={(el) => setCategoryName(el?.target?.value)}
              />
              <small style={{ color: '#666', fontSize: '12px' }}>
                {categoryName?.length || 0}/50 characters
              </small>
            </div>
            <button className="button-red" onClick={uploadData}>
              {categoryData?.id ? "Update Category" : "Add Category"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}